-- Identifiers are generated by the Rust application; no UUID extension is needed.
CREATE TABLE employees (
    id UUID PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT employees_name_valid
        CHECK (char_length(name) <= 120 AND char_length(btrim(name)) > 0),
    CONSTRAINT employees_email_valid
        CHECK (char_length(email) BETWEEN 1 AND 254),
    CONSTRAINT employees_email_canonical
        CHECK (email = lower(btrim(email))),
    CONSTRAINT employees_email_key UNIQUE (email),
    CONSTRAINT employees_status_valid CHECK (status IN ('active', 'inactive'))
);

CREATE TABLE assets (
    id UUID PRIMARY KEY,
    asset_tag TEXT NOT NULL,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    operational_status TEXT NOT NULL DEFAULT 'in_service',
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT assets_asset_tag_valid
        CHECK (char_length(asset_tag) BETWEEN 1 AND 64
               AND char_length(btrim(asset_tag)) > 0),
    CONSTRAINT assets_asset_tag_canonical CHECK (asset_tag = upper(btrim(asset_tag))),
    CONSTRAINT assets_asset_tag_key UNIQUE (asset_tag),
    CONSTRAINT assets_name_valid
        CHECK (char_length(name) <= 120 AND char_length(btrim(name)) > 0),
    CONSTRAINT assets_category_valid
        CHECK (char_length(category) <= 60 AND char_length(btrim(category)) > 0),
    CONSTRAINT assets_operational_status_valid
        CHECK (operational_status IN ('in_service', 'maintenance', 'retired'))
);

CREATE TABLE assignments (
    id UUID PRIMARY KEY,
    employee_id UUID NOT NULL REFERENCES employees (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    asset_id UUID NOT NULL REFERENCES assets (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    issued_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    expected_return_at TIMESTAMPTZ,
    returned_at TIMESTAMPTZ,
    condition_out TEXT NOT NULL,
    condition_in TEXT,
    version INTEGER NOT NULL DEFAULT 1,
    CONSTRAINT assignments_condition_out_valid CHECK (condition_out IN ('good', 'fair')),
    CONSTRAINT assignments_condition_in_valid
        CHECK (condition_in IS NULL OR condition_in IN ('good', 'fair', 'damaged')),
    CONSTRAINT assignments_version_positive CHECK (version > 0),
    CONSTRAINT assignments_expected_return_after_issue
        CHECK (expected_return_at IS NULL OR expected_return_at > issued_at),
    CONSTRAINT assignments_return_not_before_issue
        CHECK (returned_at IS NULL OR returned_at >= issued_at),
    CONSTRAINT assignments_return_details_paired
        CHECK ((returned_at IS NULL AND condition_in IS NULL)
               OR (returned_at IS NOT NULL AND condition_in IS NOT NULL))
);

-- History is retained, but a physical asset can have only one outstanding issue.
CREATE UNIQUE INDEX one_open_assignment_per_asset
    ON assignments (asset_id)
    WHERE returned_at IS NULL;

CREATE INDEX assignments_employee_history_idx
    ON assignments (employee_id, issued_at DESC, id DESC);

CREATE INDEX assignments_asset_history_idx
    ON assignments (asset_id, issued_at DESC, id DESC);
